import re


def title_of(html: str) -> str:
    """Return the text between the first <title> and </title> in html.

    The html argument is an already-fetched page; this function must not
    perform any network access. Returns an empty string when there is no
    title element or it is not closed.
    """
    match = re.search(r"<title\b[^>]*>(.*?)</title\s*>", html, re.IGNORECASE | re.DOTALL)
    if match is None:
        return ""
    return match.group(1)


def test_simple_title() -> None:
    assert title_of("<html><head><title>Hello</title></head></html>") == "Hello"


def test_missing_title_returns_empty() -> None:
    assert title_of("<html><body>no head here</body></html>") == ""


def test_tag_matching_is_case_insensitive() -> None:
    assert title_of("<HTML><TITLE>Shout</TITLE></HTML>") == "Shout"


def test_unclosed_title_returns_empty() -> None:
    assert title_of("<title>never closes") == ""


def test_first_title_wins() -> None:
    assert title_of("<title>One</title><title>Two</title>") == "One"
